@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label for="warehouse-select"><strong>Warehouse:</strong></label>
    <select id="warehouse-select" class="form-select form-select-sm" 
            value="@WarehouseState.SelectedWarehouseId" @onchange="OnWarehouseChanged">
        @foreach (var (id, name) in WarehouseState.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _handler;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(warehouseId))
        {
            WarehouseState.SetWarehouse(warehouseId);
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _handler;
    }
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@inject WarehouseState WarehouseState
@implements IDisposable

<span class="alert-badge" title="Low stock items">
    @if (AlertService.LowStockCount > 0)
    {
        <span class="badge bg-danger">@AlertService.LowStockCount</span>
    }
    else
    {
        <span class="badge bg-success">0</span>
    }
</span>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        _warehouseHandler = async () =>
        {
            await AlertService.RefreshAsync();
            await InvokeAsync(StateHasChanged);
        };
        WarehouseState.OnChange += _warehouseHandler;
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
    }
}

